solution:
const a = 1;
const b = 2;
switch (a) {
  case 1:
    switch (b) {
      case 1:
        console.log('both 1');
        break;
      case 2:
        console.log('a=1 b=2');
        break;
    }
    break;
  case 2:
    console.log('a=2');
    break;
}
